\documentclass{article}
\usepackage{pgfplots}
\usepackage{tikz}
\usetikzlibrary{arrows} %% Can be useful, not essential
\usetikzlibrary{intersections} %% Can be useful, not essential
\usepgfplotslibrary{fillbetween} %% Can be useful, not essential

\begin{document}

\definecolor{deepskyblue}{rgb}{0.173,0.447,0.682}
\definecolor{orangepeel}{rgb}{0.902, 0.624, 0}
\definecolor{lightyellow}{rgb}{0.953,0.882,0.388}
\definecolor{darkgreen}{rgb}{0.271, 0.608, 0.463}
\definecolor{lightblue}{rgb}{0.484,0.702,0.894}
\definecolor{rustred}{rgb}{0.784,0.392,0.149}
\definecolor{fadedpink}{rgb}{0.753,0.494,0.643}

\pagestyle{empty} %% IMPORTANT
\begin{tikzpicture}

	\begin{axis}[
	legend cell align={left},
	tick label style={font=\footnotesize},
	label style={font=\small},
	legend pos=outer north east,
	legend style={font=\footnotesize},
	tick style={draw=black},
	axis line style = thick,
	axis y line = middle,
	axis x line = middle,
	axis equal,
	%grid = both,
	xmin = -3.2,
	xmax = 3.2,
	ymin = -1.5,
	ymax = 4.5,
	xtick = {0},
	ytick = {0},    
	xlabel = $x$,
	ylabel = {$y$},
	xlabel style={below right},
	ylabel style={above left},
	every axis x label/.style={
	at={(ticklabel* cs:1.02)},anchor=west,},
	every axis y label/.style={at={(ticklabel* cs:1.02)}, anchor=south,}
	]

	\begin{scope}
		\path[clip] plot[domain=0:360, samples=180] (axis cs: {(1+sin(\x))*cos(\x)}, {(1+sin(\x))*sin(\x)}) (current page.north east) 
			-- (current page.south east) -- (current page.south west)
			-- (current page.north west) -- (current page.north east);
		\addplot [data cs=polar, domain=0:360, samples=180, draw=none,
			fill = deepskyblue!40, fill opacity = 0.5,
			line width=1pt,	smooth](x, {2+2*sin(x)});
	\end{scope}

	% Outer curve
	\addplot [data cs=polar, domain=0:360, samples=180, rustred,
		line width=1pt,	smooth](x, {2+2*sin(x)});
	%\addlegendentry{$r=2(1+\sin\theta)$}

	% Inner curve
	\addplot [data cs=polar, domain=0:360, samples=180, deepskyblue,
		line width=1pt,	smooth](x, {1+sin(x)});
	%\addlegendentry{$r=1+\sin\theta$}



	\node[rustred] at (axis cs: 2.1,4.1) {$r=2(1+\sin\theta)$};
	\node[deepskyblue] at (axis cs: -1.4,2.1) {$r=1+\sin\theta$};

	%Arrow
	\draw[->, very thick, orangepeel] (axis cs:0,0) -- (axis cs:{4*cos(45)},{4*sin(45)});

	\end{axis}
\end{tikzpicture}
\end{document}

